UPDATE ingredient SET public_summary = 'Cocoa powder, often simply cocoa, is an aromatic powder derived from the seeds of the Theobroma cacao tree. It is produced by roasting and grinding the seeds, referred to as cocoa beans, and then removing most of the cocoa butter from the resulting paste. Usually sold as a fine powder, cocoa is widely used in baking and beverages, notably hot cocoa, because of its intense chocolate flavor without most of the fat found in cocoa beans. The two main types are natural cocoa powder and Dutch-processed cocoa powder, both of which are available in various fat percentages.
The (non-fat) cocoa solids that make up most of cocoa powder consist primarily of carbohydrates, dietary fiber and protein. They also contain significant amounts of minerals such as iron and magnesium. In addition, cocoa is rich in polyphenols, particularly flavonoids. High-fat cocoa powder is also naturally calorie-dense.', image_url = 'https://i.pinimg.com/originals/00/4c/0e/004c0e1099458e293af59123691fba52.png' WHERE slug = 'cocoa-powder';
UPDATE ingredient SET public_summary = 'Cumin ( ,  ; US also  ; Cuminum cyminum) is a flowering plant in the family Apiaceae, native to the Irano-Turanian Region. Its seeds – each one contained within a fruit, which is dried – are used in the cuisines of many cultures in both whole and ground form. Although cumin is used in traditional medicine, there is no high-quality evidence that it is safe or effective as a therapeutic agent.', image_url = 'https://www.chowhound.com/img/gallery/everything-you-need-to-know-about-cooking-with-cumin/l-intro-1718807966.jpg' WHERE slug = 'cumin';
UPDATE ingredient SET public_summary = 'No verified summary currently available for this ingredient.', image_url = 'https://www.orderbtw.com/cdn/shop/files/attapattipremiuming200g_1445x.jpg?v=1759146515' WHERE slug = 'raising-agents-503-ii';
UPDATE ingredient SET public_summary = 'No verified summary currently available for this ingredient.', image_url = 'https://images.openfoodfacts.org/images/products/002/460/001/0030/packaging_en.17.full.jpg' WHERE slug = 'lodized-salt';
UPDATE ingredient SET public_summary = 'Black pepper (Piper nigrum) is a flowering vine in the family Piperaceae, cultivated for its fruit (the peppercorn), which is usually dried and used as a spice and seasoning. The fruit is a drupe (stonefruit) which is about 5 mm (1⁄4 in) in diameter (fresh and fully mature), dark red, and contains a stone which encloses a single pepper seed. Peppercorns and the ground pepper derived from them may be described simply as pepper, or more precisely as black pepper (cooked and dried unripe fruit), green pepper (dried unripe fruit), or white pepper (ripe fruit seeds).
Black pepper is native to South Asia. Ground, dried, and cooked peppercorns have been used since antiquity, both for flavour and as a traditional medicine. Black pepper is one of the most commonly traded spices in the world. Its spiciness is due to the chemical compound piperine, which is a different kind of spiciness from that of capsaicin characteristic of chilli peppers. It is ubiquitous in the Western world as a seasoning and is often paired with salt and available on dining tables in shakers or mills.', image_url = 'https://easyandhealthyrecipes.com/images/3s/2022/12/h1-2-scaled.jpg' WHERE slug = 'black-pepper';
UPDATE ingredient SET public_summary = 'No verified summary currently available for this ingredient.', image_url = 'https://www.cnadditives.com/uploads/31598/pgpr-e476-food-emulsifier-applications13e02.jpg' WHERE slug = 'emulsifiers-442-476';
