UPDATE ingredient SET public_summary = 'Garlic powder is a spice that is derived from dehydrated garlic and used in cooking for flavor enhancement. The process of making garlic powder includes drying and dehydrating the vegetable, then powdering it through machinery or home-based appliances depending on the scale of production. Garlic powder is a common component of spice mix. It is also a common component of seasoned salt.', image_url = 'https://www.marthastewart.com/thmb/0IJ204h9eWw-EVfdCYcNYBTnQyc=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/power-of-garlic-powder-getty-1023-4b070d93e22b4765be0f18995d55723e.jpg' WHERE slug = 'garlic-powder';
UPDATE ingredient SET public_summary = 'Baking powder is a dry chemical leavening agent, a mixture of a carbonate or bicarbonate and a weak acid. The base and acid are prevented from reacting prematurely by the inclusion of a desiccant such as cornstarch. Baking powder is used to increase the volume and lighten the texture of baked goods. It works by releasing carbon dioxide gas into a batter or dough through an acid–base reaction, causing bubbles in the wet mixture to expand and thus leavening the mixture.  
The first commercially sold baking powder ever was Borwick''s Baking Powder, launched in England in 1842 by George Borwick, who had spent eleven years from 1831 perfecting a formula passed to him by his father-in-law, a chemist, as a yeast substitute for home baking. The following year, in 1843, pharmacist Alfred Bird developed his own single-acting baking powder (meaning that it releases all of its carbon dioxide as soon as it is dampened). In 1856, Eben Norton Horsford, the Rumford Professor at Harvard University, received an American patent, for monocalcium phosphate, for baking powder. In the 1860s, Horsford developed the first double-acting baking powder, which releases some carbon dioxide when dampened and later releases more of the gas when heated by baking
Baking powder is used instead of yeast for end-products where fermentation flavors would be undesirable,  
or where the batter lacks the elastic structure to hold gas bubbles for more than a few minutes, and to speed the production of baked goods. Because carbon dioxide is released at a faster rate through the acid–base reaction than through fermentation, breads made by chemical leavening are called quick breads.  The introduction of baking powder was revolutionary in minimizing the time and labor required to make breadstuffs. It led to the creation of new types of cakes, cookies, biscuits, and other baked goods.', image_url = 'https://images.openfoodfacts.org/images/products/001/990/000/3202/ingredients_en.3.full.jpg' WHERE slug = 'baking-powder';
UPDATE ingredient SET public_summary = 'No verified summary currently available for this ingredient.', image_url = 'https://www.ragus.co.uk/wp-content/uploads/2018/09/Refined_vs_Natural_Sugars_01_ss_2191871297_1295x715px.jpg' WHERE slug = 'refined-sugar';
UPDATE ingredient SET public_summary = 'Wheat flour is a powder made from the grinding of common wheat used for human consumption. Wheat varieties are called "soft" or "weak" if gluten content is low, and are called "hard" or "strong" if they have high gluten content. Hard flour, or bread flour, is high in gluten, with 12% to 14% gluten content, and its dough has elastic toughness that holds its shape well once baked. Soft flour is comparatively low in gluten and thus results in a loaf with a finer, crumbly texture. Soft flour, in the US, is usually divided into cake flour, which is the lowest in gluten, and pastry flour, which has slightly more gluten than cake flour.
In terms of the parts of the grain (the grass fruit) used in flour—the endosperm or protein/starchy part, the germ or protein/fat/vitamin-rich part, and the bran or fiber part—there are three general types of flour. White flour is made from the endosperm only. Brown flour includes some of the grain''s germ and bran, while whole grain or wholemeal flour is made from the entire grain, including the bran, endosperm, and germ. Germ flour is made from the endosperm and germ, excluding the bran.', image_url = 'https://img.freepik.com/premium-photo/flour-delicious-food-ingredients-healthy-wheat_1015293-45799.jpg' WHERE slug = 'wheat-flour';
